UPDATE questions SET
  choices = $EXPL$["Extend log retention to one year using tiered storage to meet regulatory requirements","A 30-day retention period is sufficient for all regulatory frameworks","Delete logs immediately after review to minimize storage expenditures","No regulatory frameworks mandate specific log retention periods"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (A): Per NIST SP 800-92, Section 4.2, log retention periods must align with regulatory and organizational requirements. When regulations mandate one-year retention, tiered storage (hot for recent, cold for older logs) balances cost with compliance and accessibility for investigations.
Wrong (B): A 30-day retention period fails to meet the one-year regulatory requirement and would leave the organization non-compliant.
Wrong (C): Deleting logs immediately eliminates the audit trail needed for incident investigations and regulatory compliance.
Wrong (D): Multiple frameworks (HIPAA, PCI DSS, SOX) specify minimum log retention periods that organizations must follow.$EXPL$
WHERE id = 3673;

-- Q3675: Security Controls and Monitoring [medium/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Privilege escalation by an external attacker","Denial of access due to overly restrictive controls","Rapid growth of organizational role definitions","Privilege creep from accumulated, unrevoked permissions"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (D): Per NIST SP 800-53 Rev. 5, control AC-2, organizations must periodically review user accounts to ensure access rights remain appropriate. Privilege creep occurs when users accumulate permissions from previous roles that are never revoked, violating least privilege.
Wrong (A): Privilege escalation is an intentional attack technique, not a gradual accumulation from role changes.
Wrong (B): Access denial is the opposite problem — restricting legitimate access rather than allowing excessive access.
Wrong (C): Role explosion refers to proliferation of role definitions in RBAC systems, not accumulation of individual user permissions.$EXPL$
